import { formatNilai } from './hitung.js';

// Page numbers are taken from stored source metadata, never generated by the LLM.
export function documentUrl(source) {
  try {
    const u = new URL(source.url);
    if (u.protocol !== 'https:' || u.username || u.password) return null;
    const page = String(source.halaman_atau_tabel ?? '').match(/(?:hlm\.?|halaman)\s*(\d+)/i)?.[1];
    if (/\.pdf$/i.test(u.pathname) && page) u.hash = `page=${page}`;
    return u.href;
  } catch { return null; }
}

// Explicit scopes prevent a sector/pool budget being treated as one program's budget.
const scopes = {
  'jejak-pip': ['paket-beasiswa', 'pip'],
  'jejak-kip-kuliah': ['paket-beasiswa', 'kip-kuliah'],
  'jejak-bos': ['seluruh-tkd', 'bos'],
  'jejak-pbi-jkn': ['pbi-jkn', 'pbi-jkn'],
  'jejak-skrining-kesehatan': ['skrining', 'skrining'],
  'jejak-pkh': ['pkh', 'pkh'],
  'jejak-jalan-nasional': ['seluruh-infrastruktur', 'jalan'],
  'jejak-subsidi-energi': ['subsidi-dan-kompensasi', 'subsidi-energi'],
};
export function traceEvidence(item) {
  const tahun = item.tahun_anggaran;
  const pair = scopes[item.id];
  const stages = ['alokasi','realisasi','capaian'].map(kind => ({
    ...item.tahap[kind],
    tahun_anggaran: kind === 'capaian' && item.id === 'jejak-subsidi-energi' ? 2025 : tahun,
    pos: `${item.nama} — ${item.tahap[kind].label}`,
    jenis_angka: kind === 'alokasi' ? 'Anggaran' : kind === 'realisasi' ? 'Realisasi' : 'Capaian Output',
    cakupan: kind === 'alokasi' ? pair?.[0] : pair?.[1],
  }));
  const [a,r,c] = stages;
  const available = s => Boolean(documentUrl(s) && s.halaman_atau_tabel && s.kutipan);
  const comparable = Boolean(pair && a.cakupan === r.cakupan && a.tahun_anggaran === r.tahun_anggaran && a.satuan === r.satuan && Number.isFinite(a.nilai) && a.nilai > 0 && Number.isFinite(r.nilai) && available(a) && available(r));
  const warnings = [];
  if (!comparable) warnings.push('Pagu dan realisasi belum dapat dihitung sebagai persentase satu program: cakupan atau kelengkapan datanya berbeda.');
  if (c.tahun_anggaran !== tahun) warnings.push(`Capaian yang dimuat berasal dari TA ${c.tahun_anggaran}; bukan hasil belanja TA ${tahun}.`);
  return { stages, comparable, ratio: comparable ? r.nilai / a.nilai * 100 : null, warnings };
}

export function evidenceText(rows) {
  return rows.filter(s => documentUrl(s) && s.dokumen && s.kutipan && s.halaman_atau_tabel)
    .map(s => [
      `${s.pos ?? s.label}: ${s.jenis_angka ?? 'Informasi'}${Number.isFinite(s.nilai) ? ' ' + formatNilai(s) : s.output_fisik ? ' — ' + s.output_fisik : ''}.`,
      `TA ${s.tahun_anggaran}; ${s.posisi_data ?? s.label ?? 'periode mengikuti sumber'}.`,
      `Cakupan: ${s.cakupan ?? 'mengikuti dokumen'}.`,
      `Sumber: ${s.dokumen}; ${s.halaman_atau_tabel}.`,
      `Kutipan: ${s.kutipan}`,
      documentUrl(s),
    ].join('\n')).join('\n\n');
}
